11	/// ## What it does
12	/// Checks for the use of non-lowercase variable names in functions.
13	///
14	/// ## Why is this bad?
15	/// [PEP 8] recommends that all function variables use lowercase names:
16	///
17	/// > Function names should be lowercase, with words separated by underscores as necessary to
18	/// > improve readability. Variable names follow the same convention as function names. mixedCase
19	/// > is allowed only in contexts where that's already the prevailing style (e.g. threading.py),
20	/// > to retain backwards compatibility.
21	///
22	/// ## Example
23	/// ```python
24	/// def my_function(a):
25	///     B = a + 3
26	///     return B
27	/// ```
28	///
29	/// Use instead:
30	/// ```python
31	/// def my_function(a):
32	///     b = a + 3
33	///     return b
34	/// ```
35	///
36	/// ## Options
37	/// - `lint.pep8-naming.ignore-names`
38	/// - `lint.pep8-naming.extend-ignore-names`
39	///
40	/// [PEP 8]: https://peps.python.org/pep-0008/#function-and-variable-names
41	#[derive(ViolationMetadata)]
42	#[violation_metadata(stable_since = "v0.0.89")]
43	pub(crate) struct NonLowercaseVariableInFunction {
44	    name: String,
45	}
46	
47	impl Violation for NonLowercaseVariableInFunction {
48	    #[derive_message_formats]
49	    fn message(&self) -> String {
50	        let NonLowercaseVariableInFunction { name } = self;
51	        format!("Variable `{name}` in function should be lowercase")
52	    }
53	}
54	
55	/// N806
56	pub(crate) fn non_lowercase_variable_in_function(checker: &Checker, expr: &Expr, name: &str) {
57	    if str::is_lowercase(name) {
58	        return;
59	    }
60	
61	    // Ignore globals.
62	    if checker
63	        .semantic()
64	        .lookup_symbol(name)
65	        .is_some_and(|id| checker.semantic().binding(id).is_global())
66	    {
67	        return;
68	    }
69	
70	    let parent = checker.semantic().current_statement();
71	    if helpers::is_named_tuple_assignment(parent, checker.semantic())
72	        || helpers::is_typed_dict_assignment(parent, checker.semantic())
73	        || helpers::is_type_var_assignment(parent, checker.semantic())
74	        || helpers::is_type_alias_assignment(parent, checker.semantic())
75	        || helpers::is_django_model_import(name, parent, checker.semantic())
76	    {
77	        return;
78	    }
79	
80	    // Ignore explicitly-allowed names.
81	    if checker.settings().pep8_naming.ignore_names.matches(name) {
82	        return;
83	    }
84	
85	    checker.report_diagnostic(
86	        NonLowercaseVariableInFunction {
87	            name: name.to_string(),
88	        },
89	        expr.range(),
90	    );
91	}
