10	/// ## What it does
11	/// Checks for global variable names that follow the `mixedCase` convention.
12	///
13	/// ## Why is this bad?
14	/// [PEP 8] recommends that global variable names should be lower case and
15	/// separated by underscores (also known as `snake_case`).
16	///
17	/// > ### Global Variable Names
18	/// > (Let’s hope that these variables are meant for use inside one module
19	/// > only.) The conventions are about the same as those for functions.
20	/// >
21	/// > Modules that are designed for use via `from M import *` should use the
22	/// > `__all__` mechanism to prevent exporting globals, or use the older
23	/// > convention of prefixing such globals with an underscore (which you might
24	/// > want to do to indicate these globals are “module non-public”).
25	/// >
26	/// > ### Function and Variable Names
27	/// > Function names should be lowercase, with words separated by underscores
28	/// > as necessary to improve readability.
29	/// >
30	/// > Variable names follow the same convention as function names.
31	/// >
32	/// > mixedCase is allowed only in contexts where that’s already the prevailing
33	/// > style (e.g. threading.py), to retain backwards compatibility.
34	///
35	/// ## Example
36	/// ```python
37	/// myVariable = "hello"
38	/// another_variable = "world"
39	/// yet_anotherVariable = "foo"
40	/// ```
41	///
42	/// Use instead:
43	/// ```python
44	/// my_variable = "hello"
45	/// another_variable = "world"
46	/// yet_another_variable = "foo"
47	/// ```
48	///
49	/// ## Options
50	/// - `lint.pep8-naming.ignore-names`
51	/// - `lint.pep8-naming.extend-ignore-names`
52	///
53	/// [PEP 8]: https://peps.python.org/pep-0008/#global-variable-names
54	#[derive(ViolationMetadata)]
55	#[violation_metadata(stable_since = "v0.0.89")]
56	pub(crate) struct MixedCaseVariableInGlobalScope {
57	    name: String,
58	}
59	
60	impl Violation for MixedCaseVariableInGlobalScope {
61	    #[derive_message_formats]
62	    fn message(&self) -> String {
63	        let MixedCaseVariableInGlobalScope { name } = self;
64	        format!("Variable `{name}` in global scope should not be mixedCase")
65	    }
66	}
67	
68	/// N816
69	pub(crate) fn mixed_case_variable_in_global_scope(checker: &Checker, expr: &Expr, name: &str) {
70	    if !helpers::is_mixed_case(name) {
71	        return;
72	    }
73	
74	    let parent = checker.semantic().current_statement();
75	    if helpers::is_named_tuple_assignment(parent, checker.semantic()) {
76	        return;
77	    }
78	
79	    if checker.settings().pep8_naming.ignore_names.matches(name) {
80	        return;
81	    }
82	
83	    checker.report_diagnostic(
84	        MixedCaseVariableInGlobalScope {
85	            name: name.to_string(),
86	        },
87	        expr.range(),
88	    );
89	}
